import java.util.*;

public class Main {
    static class MedianFinder {
        List<Integer> data = new ArrayList<>();

        void addNum(int num) {
            data.add(num);
        }

        double findMedian() {
            List<Integer> sorted = new ArrayList<>(data);
            Collections.sort(sorted);
            int n = sorted.size();
            int mid = n / 2;
            if (n % 2 == 1) return sorted.get(mid);
            return (sorted.get(mid - 1) + sorted.get(mid)) / 2.0;
        }
    }

